/**
 * Shared types for apple-fm.
 *
 * The Node layer never imports `FoundationModels` directly — it spawns the Swift
 * helper (`apple-fm-helper`) and exchanges line-delimited JSON. These types
 * describe that wire contract and the public API built on top of it.
 */
/** A conversational role. The on-device model is instructed via `system`. */
type Role = 'user' | 'assistant';
/** One turn in a conversation. */
interface Message {
    role: Role;
    content: string;
}
/** Per-request generation knobs, passed through to the on-device session. */
interface GenerateOptions {
    /** Sampling temperature (0–2). Omitted ⇒ the model's default. */
    temperature?: number;
    /** Cap on the response length, in tokens. Omitted ⇒ the model's default. */
    maxTokens?: number;
}
/**
 * A single generation request sent to the helper's `--generate` mode.
 *
 * Provide either `prompt` (a single user turn) or `messages` (a full
 * conversation, replayed as the session transcript). `schema`, when present,
 * requests guided generation that conforms to the given JSON Schema.
 */
interface GenerateRequest {
    /** Instructions for the session (the system prompt). */
    system?: string;
    /** A single user turn. Mutually exclusive with `messages`. */
    prompt?: string;
    /** A full conversation. Mutually exclusive with `prompt`. */
    messages?: Message[];
    /** JSON Schema for guided/structured output. */
    schema?: unknown;
    /** Generation knobs. */
    options?: GenerateOptions;
    /** Stream partial output as `delta` events (default: false). */
    stream?: boolean;
}
/**
 * Why the on-device model is or isn't usable right now. The first three +
 * `unknown` come from the Swift helper; `unsupportedPlatform` is reported by the
 * Node layer *without* running the helper, when the OS/CPU can't run it at all
 * (not macOS on Apple Silicon).
 */
type UnavailableReason = 'deviceNotEligible' | 'appleIntelligenceNotEnabled' | 'modelNotReady' | 'unsupportedPlatform' | 'unknown';
/** Result of `apple-fm-helper --probe`. */
interface ProbeResult {
    available: boolean;
    /** Present only when `available` is false. */
    reason?: UnavailableReason;
}
/**
 * One line of helper output (NDJSON). When streaming, freeform text emits `delta`
 * events (append the suffix) while guided/structured output emits `snapshot`
 * events (the full partial value — replace, since structured partials are not
 * append-only). Every successful generation ends with exactly one `result`.
 * Failures emit a single `error`.
 */
type HelperEvent = {
    type: 'delta';
    text: string;
} | {
    type: 'snapshot';
    content: string;
} | {
    type: 'result';
    content: string;
} | {
    type: 'error';
    code: string;
    message: string;
};
/** Options for locating + invoking the helper binary. */
interface HelperOptions {
    /** Explicit path to the helper binary. Overrides discovery. */
    binPath?: string;
    /** Milliseconds before a one-shot generation is aborted (default 120_000). */
    timeoutMs?: number;
}
/** Callback fired for each streamed text chunk (append the suffix). */
type DeltaHandler = (text: string) => void;
/**
 * Callback fired for each full partial value during guided/structured streaming.
 * Each call carries the complete current JSON (replace, not append) — structured
 * partials are not append-only.
 */
type SnapshotHandler = (content: string) => void;

/** Environment variable that pins the helper binary path. */
declare const HELPER_BIN_ENV = "APPLE_FM_BIN";
/**
 * Whether this platform can run the bundled on-device helper at all: macOS on
 * Apple Silicon. (Whether the *model* is usable then — macOS 26+, Apple
 * Intelligence enabled — is what {@link probe} checks.) apple-fm installs on any
 * OS so it can be a dependency of cross-platform projects; off-platform it
 * degrades gracefully rather than crashing — `probe` reports `unsupportedPlatform`
 * and `generate` / `ChatSession` throw a clear `[unsupportedPlatform]` error.
 */
declare function isPlatformSupported(): boolean;
/**
 * Resolve the helper binary path: an explicit `binPath`, then the `APPLE_FM_BIN`
 * override (trusted as-is — an advanced/testing escape hatch), then the prebuilt
 * binary bundled with the package (`bin/apple-fm-helper`), addressed by an absolute
 * path relative to this module. There is **no bare-name `PATH` lookup** — the helper
 * is never resolved off `PATH`, so it can't be shadowed by a planted binary (AFM-66).
 */
declare function resolveHelperPath(options?: HelperOptions): string;
/** Ask the helper whether the on-device model is available right now. */
declare function probe(options?: HelperOptions): Promise<ProbeResult>;
/**
 * Run one generation. When `request.stream` is set, freeform text is forwarded to
 * `onDelta` (append the suffix) and guided/structured output to `onSnapshot` (the
 * full partial JSON each time — replace, since structured partials are not
 * append-only). The resolved value is always the full text (or, for guided
 * generation, the complete JSON string).
 */
declare function generate(request: GenerateRequest, options?: HelperOptions, onDelta?: DeltaHandler, onSnapshot?: SnapshotHandler): Promise<string>;

/**
 * Per-call permission policy for tool calling (FR-14 / AF-5 phase 2; see
 * docs/10-permissions.md). Consulted by the live-session dispatcher *before* a
 * tool runs. Kept entirely in Node — the Swift helper never decides policy.
 *
 * A request resolves to `allow` / `deny` / `ask`. `ask` prompts via an injected
 * {@link PermissionAsker} (the REPL supplies one bound to readline); with no asker
 * (non-interactive / piped), `ask` denies — a script never silently runs a tool. An
 * "always" answer is remembered for the process lifetime.
 *
 * Rules are keyed by tool name, or by a finer `tool:key` so that allowing one
 * command (a `bash:git status` rule) or one path (`read:/etc`) doesn't allow all of
 * the tool. How a keyed rule's key matches a call's key is decided by the tool's
 * {@link Tool.matchKey} — **exact equality** by default (never a prefix, so a grant
 * can't be extended with shell metacharacters or `..`), `read` widening it to a
 * resolved path boundary, `bash` keeping `allow` exact but making `deny` a broad
 * best-effort token match (AFM-63 / AFM-67). A permissive *default* never
 * blanket-approves a {@link Tool.dangerous} tool (AFM-64).
 */
